import{_ as e,o as d,c as r,a3 as a}from"./chunks/framework.DQ-7HQaQ.js";const m=JSON.parse('{"title":"Glossary","description":"Plain-language definitions of knowledge, workflow and deployment terms.","frontmatter":{"title":"Glossary","description":"Plain-language definitions of knowledge, workflow and deployment terms."},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md","lastUpdated":1794376220000}'),n={name:"reference/glossary.md"};function i(o,t,s,l,c,p){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="shared-vocabulary" tabindex="-1">Shared vocabulary <a class="header-anchor" href="#shared-vocabulary" aria-label="Permalink to &quot;Shared vocabulary&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Term</th><th>Meaning here</th></tr></thead><tbody><tr><td>Artifact</td><td>Immutable source or derived bytes, identified by a cryptographic digest.</td></tr><tr><td>Acquisition</td><td>Where, when and how material was obtained.</td></tr><tr><td>Mention</td><td>A specific name or reference at an exact source location.</td></tr><tr><td>Entity</td><td>A stable identity such as a person, place or incident.</td></tr><tr><td>Alias</td><td>A context-dependent name; not globally unique.</td></tr><tr><td>Claim</td><td>A qualified proposition, including relevant time, polarity or modality.</td></tr><tr><td>Assertion</td><td>What a particular source says about a claim.</td></tr><tr><td>Provenance</td><td>The trail from source through processing and review to published knowledge.</td></tr><tr><td>Resolution</td><td>A reviewable decision connecting mentions to identities.</td></tr><tr><td>Draft / proposal</td><td>Candidate changes not yet published.</td></tr><tr><td>Revision</td><td>An identified published state retained for reproducible evidence references.</td></tr><tr><td>Graph</td><td>Typed relationships between identities, claims and evidence.</td></tr><tr><td>Embedding space</td><td>Vector representation defined by a model and preprocessing contract.</td></tr><tr><td>Hybrid retrieval</td><td>Combining available lexical search, vector candidates and graph relationships.</td></tr><tr><td>RAG</td><td>Retrieval-augmented generation: providing selected evidence to a model before it answers.</td></tr><tr><td>NER</td><td>Named-entity recognition: identifying mentions, not proving canonical identity.</td></tr><tr><td>DAG</td><td>A task dependency graph with no cycles.</td></tr><tr><td>Lease</td><td>A time-bounded assignment authorizing a worker attempt.</td></tr><tr><td>Fencing epoch</td><td>An attempt identity that lets the store reject an older result.</td></tr><tr><td>Idempotency</td><td>Repeating an accepted request does not repeat its durable effect.</td></tr><tr><td>Capability</td><td>A versioned operation, independent of its implementation.</td></tr><tr><td>SSE</td><td>Server-sent event framing for incremental browser delivery.</td></tr><tr><td>Projection</td><td>An authorized, rebuildable view of durable records.</td></tr><tr><td>Release</td><td>A tested software artifact plus approved configuration and compatibility information.</td></tr></tbody></table><p>The <a href="./../project/knowledge">knowledge rules</a> and <a href="./../project/plugins">worker contract</a> define the invariants behind these terms.</p>',3)])])}const u=e(n,[["render",i]]);export{m as __pageData,u as default};
